create table if not exists public.foods (
  id uuid primary key default gen_random_uuid(),
  trainer_id uuid references auth.users(id) on delete cascade,
  name text not null,
  category text not null default 'outros',
  kcal numeric not null default 0,
  protein_g numeric not null default 0,
  carbs_g numeric not null default 0,
  fat_g numeric not null default 0,
  created_at timestamptz not null default now()
);
create index if not exists foods_name_idx on public.foods using gin (to_tsvector('portuguese', name));
alter table public.foods enable row level security;
drop policy if exists foods_read on public.foods;
create policy foods_read on public.foods for select to authenticated using (trainer_id is null or trainer_id = (select auth.uid()));
drop policy if exists foods_write on public.foods;
create policy foods_write on public.foods for all to authenticated using (trainer_id = (select auth.uid())) with check (trainer_id = (select auth.uid()));
alter table public.nutrition_plans add column if not exists target_kcal numeric;
alter table public.nutrition_plans add column if not exists target_protein_g numeric;
alter table public.nutrition_plans add column if not exists target_carbs_g numeric;
alter table public.nutrition_plans add column if not exists target_fat_g numeric;
alter table public.nutrition_plans add column if not exists meals jsonb not null default '[]'::jsonb;
